<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useI18n} from 'vue-i18n'
import {Download,ImagePlus,LayoutGrid,LogOut,Moon,Settings,Sparkles,Sun,Trash2,Upload,WandSparkles} from 'lucide-vue-next'
import {supabase} from './lib/supabase'
import {api} from './lib/api'
import type {Generation,Locale,ModelDescriptor,ThemeMode} from './types'
const {t,locale}=useI18n();const theme=ref<ThemeMode>(localStorage.getItem('klowerg-theme') as ThemeMode||'system');const session=ref<any>(null);const loading=ref(Boolean(supabase));const demo=!supabase
const view=ref<'studio'|'history'|'settings'>('studio');const models=ref<ModelDescriptor[]>([]);const selected=ref('gpt-image-2');const prompt=ref('');const size=ref('1024x1024');const quality=ref('standard');const aspect=ref('1:1');const generations=ref<Generation[]>([]);const active=ref<Generation|null>(null);const busy=ref(false);const error=ref('');const file=ref<File|null>(null);const preview=ref('');const analysis=ref('');const analyzing=ref(false);const email=ref('');const password=ref('');const authMode=ref<'login'|'signup'>('login');const authMessage=ref('')
const imageModels=computed(()=>models.value.filter(m=>m.kind==='image'));const chosen=computed(()=>models.value.find(m=>m.id===selected.value));const sizes=computed(()=>chosen.value?.options.size||['1024x1024']);const userEmail=computed(()=>session.value?.user?.email||'demo@klowerg.local')
function applyTheme(){const dark=theme.value==='dark'||(theme.value==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light'}function setTheme(v:ThemeMode){theme.value=v;localStorage.setItem('klowerg-theme',v);applyTheme()}function setLocale(v:Locale){locale.value=v;localStorage.setItem('klowerg-locale',v)}
async function auth(){if(!supabase){authMessage.value=t('demo');return}const result=authMode.value==='login'?await supabase.auth.signInWithPassword({email:email.value,password:password.value}):await supabase.auth.signUp({email:email.value,password:password.value});authMessage.value=result.error?.message||''}
function onFile(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(f){file.value=f;preview.value=URL.createObjectURL(f);analysis.value='' }}
async function analyze(){if(!file.value)return;analyzing.value=true;error.value='';try{analysis.value=(await api.analyze(file.value)).analysis}catch(e){error.value=e instanceof Error?e.message:t('error')}finally{analyzing.value=false}}
async function generate(){if(!prompt.value.trim()||busy.value)return;busy.value=true;error.value='';try{const result=await api.generate({prompt:prompt.value,model:selected.value,size:size.value,quality:quality.value,aspect_ratio:aspect.value,count:1,reference_analysis:analysis.value||null});active.value=result;generations.value=[result,...generations.value]}catch(e){error.value=e instanceof Error?e.message:t('error')}finally{busy.value=false}}
async function remove(id:string){try{await api.remove(id);generations.value=generations.value.filter(g=>g.id!==id);if(active.value?.id===id)active.value=null}catch(e){error.value=e instanceof Error?e.message:t('error')}}function download(url:string){const a=document.createElement('a');a.href=url;a.download='klowerg-img-flash.png';a.click()}
onMounted(async()=>{applyTheme();if(supabase){const current=await supabase.auth.getSession();session.value=current.data.session;supabase.auth.onAuthStateChange((_e,s)=>session.value=s)}try{models.value=await api.models()}catch(e){error.value=e instanceof Error?e.message:t('error')}if(session.value||demo){try{generations.value=await api.generations()}catch{}}loading.value=false});watch(selected,()=>{if(!sizes.value.includes(size.value))size.value=sizes.value[0];quality.value=chosen.value?.options.quality?.[0]||'standard'})
</script>
<template>
<div v-if="loading" class="boot"><Sparkles :size="24"/><strong>KloweRG IMG Flash</strong></div>
<div v-else class="shell"><aside class="sidebar"><div class="brand"><span class="mark"><Sparkles :size="18"/></span><span><b>KloweRG</b><small>IMG FLASH</small></span></div><p class="side-caption">{{t('tag')}}</p><nav><button :class="{active:view==='studio'}" @click="view='studio'"><WandSparkles :size="17"/>{{t('studio')}}</button><button :class="{active:view==='history'}" @click="view='history'"><LayoutGrid :size="17"/>{{t('history')}}<em v-if="generations.length">{{generations.length}}</em></button><button :class="{active:view==='settings'}" @click="view='settings'"><Settings :size="17"/>{{t('settings')}}</button></nav><div class="side-bottom"><div class="user"><span class="avatar">{{userEmail[0]?.toUpperCase()}}</span><span><b>{{userEmail}}</b><small>{{demo?t('demo'):'Supabase Auth'}}</small></span><button class="icon" @click="supabase?.auth.signOut()"><LogOut :size="15"/></button></div><small class="connected"><i/> Cavoti connected</small></div></aside>
<main><header><div class="mobile-brand"><span class="mark"><Sparkles :size="16"/></span><b>KloweRG</b></div><div class="top-actions"><span class="private"><i/> Private workspace</span><button class="icon" @click="setTheme(theme==='dark'?'light':'dark')"><Sun v-if="theme==='dark'" :size="17"/><Moon v-else :size="17"/></button><div class="langs"><button :class="{on:locale==='es'}" @click="setLocale('es')">ES</button><button :class="{on:locale==='en'}" @click="setLocale('en')">EN</button></div></div></header>
<section v-if="!session&&!demo" class="auth"><div class="auth-mark"><Sparkles :size="28"/></div><p class="eyebrow">{{t('tag')}}</p><h1>{{authMode==='login'?t('login'):t('signup')}}</h1><p>{{t('authHint')}}</p><form @submit.prevent="auth"><label>{{t('email')}}<input v-model="email" type="email" required/></label><label>{{t('password')}}<input v-model="password" type="password" minlength="6" required/></label><button class="primary wide"><Sparkles :size="16"/>{{authMode==='login'?t('login'):t('signup')}}</button></form><button class="text" @click="authMode=authMode==='login'?'signup':'login'">{{authMode==='login'?t('signup'):t('login')}}</button><small v-if="authMessage">{{authMessage}}</small></section>
<template v-else><section v-if="view==='studio'" class="workspace"><div class="hero"><div><p class="eyebrow">Image studio</p><h1>{{t('title')}}</h1><p>{{t('subtitle')}}</p></div><span class="badge"><Sparkles :size="14"/> AI creative lab</span></div><div class="grid"><section class="panel composer"><div class="panel-head"><h2><small>01</small>{{t('prompt')}}</h2><span>⌘ ↵</span></div><textarea v-model="prompt" rows="6" :placeholder="t('placeholder')" @keydown.meta.enter.prevent="generate" @keydown.ctrl.enter.prevent="generate"/><div class="examples"><button v-for="item in [t('title'),t('subtitle'),t('placeholder')]" :key="item" @click="prompt=item">{{item}}</button></div><div class="reference"><div class="panel-head"><h2><small>02</small>{{t('reference')}}</h2><ImagePlus :size="17"/></div><div class="upload"><input id="file" type="file" accept="image/png,image/jpeg,image/webp" @change="onFile"/><label for="file"><img v-if="preview" :src="preview" alt=""/><Upload v-else :size="19"/><span>{{file?.name||t('upload')}}</span></label><button v-if="file&&!analysis" class="secondary" :disabled="analyzing" @click="analyze">{{analyzing?t('analyzing'):t('analyze')}}</button></div><div v-if="analysis" class="analysis"><b>{{t('analysis')}}</b><p>{{analysis}}</p></div></div><button class="primary generate" :disabled="busy||!prompt.trim()" @click="generate"><Sparkles :size="17"/>{{busy?t('generating'):t('generate')}}<span>↗</span></button></section><aside class="panel options"><div class="panel-head"><h2><small>03</small>{{t('parameters')}}</h2><i class="live"/></div><label>{{t('model')}}<select v-model="selected"><option v-for="m in imageModels" :key="m.id" :value="m.id">{{m.name}}</option></select><small>{{chosen?.description}}</small></label><label>{{t('size')}}<select v-model="size"><option v-for="v in sizes" :key="v">{{v}}</option></select></label><label>{{t('quality')}}<select v-model="quality"><option value="standard">{{t('standard')}}</option><option value="high">{{t('high')}}</option></select></label><label>Aspect ratio<div class="segments"><button v-for="v in ['1:1','4:5','16:9']" :key="v" :class="{on:aspect===v}" @click="aspect=v">{{v}}</button></div></label><footer>Output <b>PNG · High fidelity</b></footer></aside><section class="panel canvas"><div class="panel-head"><h2><small>04</small>{{t('canvas')}}</h2><span v-if="active" class="success">Generated just now</span></div><div v-if="busy" class="empty"><span class="spinner"/><b>{{t('generating')}}</b><small>Composing light, texture and detail</small></div><div v-else-if="active" class="result"><img :src="active.images[0]?.url" alt="Generated result"/><div><button class="secondary" @click="download(active.images[0].url)"><Download :size="15"/>{{t('download')}}</button><button class="icon danger" @click="remove(active.id)"><Trash2 :size="15"/></button></div></div><div v-else class="empty"><span class="empty-mark"><Sparkles :size="23"/></span><b>{{t('empty')}}</b><small>{{t('emptyHint')}}</small></div></section></div><div v-if="error" class="error">{{error}}<button @click="error=''">×</button></div><section class="latest"><div class="section-head"><div><p class="eyebrow">Archive</p><h2>{{t('latest')}}</h2></div><button class="text" @click="view='history'">{{t('all')}} ↗</button></div><div v-if="generations.length" class="thumbs"><button v-for="g in generations.slice(0,4)" :key="g.id" @click="active=g"><img :src="g.images[0]?.url" alt=""/><span>{{g.model}}</span></button><span v-for="i in 4-generations.length" :key="i" class="placeholder"><Sparkles :size="15"/></span></div><div v-else class="archive">{{t('none')}} <span>—</span></div></section></section><section v-else-if="view==='history'" class="page"><p class="eyebrow">{{t('history')}}</p><h1>{{t('latest')}}</h1><div v-if="generations.length" class="history-grid"><article v-for="g in generations" :key="g.id"><img :src="g.images[0]?.url" alt=""/><div><span><b>{{g.model}}</b>{{g.prompt}}</span><aside><button class="icon" @click="download(g.images[0].url)"><Download :size="15"/></button><button class="icon danger" @click="remove(g.id)"><Trash2 :size="15"/></button></aside></div></article></div><div v-else class="archive">{{t('none')}}</div></section><section v-else class="page"><p class="eyebrow">{{t('settings')}}</p><h1>{{t('settings')}}</h1><div class="settings"><div><span><b>{{t('theme')}}</b><small>Choose the mood of your workspace</small></span><div class="segments"><button v-for="v in [{id:'system',label:t('system')},{id:'dark',label:t('dark')},{id:'light',label:t('light')}]" :key="v.id" :class="{on:theme===v.id}" @click="setTheme(v.id as ThemeMode)">{{v.label}}</button></div></div><div><span><b>{{t('language')}}</b><small>Interface language</small></span><div class="segments"><button :class="{on:locale==='es'}" @click="setLocale('es')">{{t('spanish')}}</button><button :class="{on:locale==='en'}" @click="setLocale('en')">{{t('english')}}</button></div></div></div></section></template></main></div>
</template>
